import{_ as i,o as a,a as t,ag as s}from"./chunks/framework.Do1Zayaf.js";const g=JSON.parse('{"title":"Roxie Query Execution: Invariants and Parsing Analysis","description":"","frontmatter":{},"headers":[],"relativePath":"aidoc/roxie-kb/query-invariants-and-parsing.md","filePath":"aidoc/roxie-kb/query-invariants-and-parsing.md","lastUpdated":1779520499000}'),n={name:"aidoc/roxie-kb/query-invariants-and-parsing.md"};function r(o,e,c,d,h,l){return a(),t("div",null,e[0]||(e[0]=[s(`<h1 id="roxie-query-execution-invariants-and-parsing-analysis" tabindex="-1">Roxie Query Execution: Invariants and Parsing Analysis <a class="header-anchor" href="#roxie-query-execution-invariants-and-parsing-analysis" aria-label="Permalink to &quot;Roxie Query Execution: Invariants and Parsing Analysis&quot;">​</a></h1><p>This document summarizes findings regarding execution efficiency in the Roxie codebase, specifically concerning XML parsing, pattern matching on the hot path, and query-invariant optimizations.</p><h2 id="_1-hot-path-parsing-and-pattern-matching" tabindex="-1">1. Hot Path Parsing and Pattern Matching <a class="header-anchor" href="#_1-hot-path-parsing-and-pattern-matching" aria-label="Permalink to &quot;1. Hot Path Parsing and Pattern Matching&quot;">​</a></h2><h3 id="identified-bottleneck-croxieserverxmlparseactivity-nextrow" tabindex="-1">Identified Bottleneck: <code>CRoxieServerXmlParseActivity::nextRow</code> <a class="header-anchor" href="#identified-bottleneck-croxieserverxmlparseactivity-nextrow" aria-label="Permalink to &quot;Identified Bottleneck: \`CRoxieServerXmlParseActivity::nextRow\`&quot;">​</a></h3><p>In <code>roxie/ccd/ccdserver.cpp</code>, the <code>CRoxieServerXmlParseActivity</code> processes incoming rows from an input stream, extracting a text field (XML/JSON) to parse. For <strong>every single input row</strong>, it extracts the invariant XPath text from the helper and creates a new parser instance from scratch:</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">            size32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> srchLen;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            helper.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getSearchText</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(srchLen, srchStr, in);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">            OwnedRoxieString</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> xmlIteratorPath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helper</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getXmlIteratorPath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            xmlParser.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setown</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">createXMLParse</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(srchStr, srchLen, xmlIteratorPath, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">));</span></span></code></pre></div><p>Internally, <code>createXMLParse</code> (in <code>common/thorhelper/thorxmlread.cpp</code>) instantiates a new <code>CXMLParse</code> object. The constructor calls <code>init()</code>, which creates and initializes a <code>CXMLMaker</code> or <code>CJSONMaker</code> object. This initialization process parses the <code>xmlIteratorPath</code> (the XPath string) and sets up a pattern-matching state machine to traverse the structural hierarchy.</p><p><strong>Impact:</strong> The setup and teardown overhead of string-parsing the XPath and initializing these parser tree structures occurs on the execution engine&#39;s hot path, multiplying the CPU cycles expended rather than securely processing the payload sequence.</p><h3 id="minimal-regexpr-impact-on-execution" tabindex="-1">Minimal RegExpr Impact on Execution <a class="header-anchor" href="#minimal-regexpr-impact-on-execution" aria-label="Permalink to &quot;Minimal RegExpr Impact on Execution&quot;">​</a></h3><ul><li><code>RegExpr</code> (from <code>jregexp.hpp</code>) is notably used in <code>roxie/ccd/ccdlistener.cpp</code> inside <code>AccessTableEntry</code> for query ACL constraints, but the compilation via <code>init()</code> occurs at initialization time. (It does use a spinlock <code>crappyUnsafeRegexLock</code> around <code>queries.find(query)</code> making it thread-unsafe, which can contend, but isn&#39;t row-level execution).</li><li>Metrics topology patterns are parsed during server startup (e.g. <code>roxie/ccd/ccdsnmp.cpp</code>). Boost regex is largely avoided in Roxie.</li></ul><h2 id="_2-query-invariant-optimizations" tabindex="-1">2. Query Invariant Optimizations <a class="header-anchor" href="#_2-query-invariant-optimizations" aria-label="Permalink to &quot;2. Query Invariant Optimizations&quot;">​</a></h2><h3 id="successfully-hoisted-invariants" tabindex="-1">Successfully Hoisted Invariants <a class="header-anchor" href="#successfully-hoisted-invariants" aria-label="Permalink to &quot;Successfully Hoisted Invariants&quot;">​</a></h3><p>Roxie already implements effective invariant hoisting by moving repetitive initialization from Activity instances (<code>CRoxieServerActivity</code>) into their respective Factories (<code>CRoxieServerActivityFactory</code>).</p><ul><li><strong>Tomita / NLP Parsing:</strong> In <code>roxie/ccd/ccdserver.cpp</code>, the Tomita/NLP parse state machine is successfully isolated. <code>CRoxieServerParseActivityFactory</code> builds <code>Owned&lt;INlpParseAlgorithm&gt; algorithm = createThorParser(rc, *helper);</code> in its constructor. The state machine is generated once when the query graph is prepared and passed down to <code>CRoxieServerStrandedParseActivity</code> instances via a pointer.</li><li><strong>Index Key Hints (<code>memKeyHint</code>):</strong> In <code>roxie/ccd/ccdactivities.cpp</code>, XML hints for preloading indexes are parsed with <code>createPTreeFromXMLString</code> inside the constructor of <code>CRoxieDiskBaseActivityFactory</code> rather than during record processing.</li></ul><h3 id="missed-hoisting-opportunities" tabindex="-1">Missed Hoisting Opportunities <a class="header-anchor" href="#missed-hoisting-opportunities" aria-label="Permalink to &quot;Missed Hoisting Opportunities&quot;">​</a></h3><p>As established above, the XML/JSON XPath configuration in <code>CRoxieServerXmlParseActivity</code> and <code>XmlRecordProcessor</code> (in <code>roxie/ccd/ccdactivities.cpp</code>) is query-invariant. The <code>helper.getXmlIteratorPath()</code> results in an unchanging string for a given factory context.</p><p>If <code>CXMLMaker</code>/<code>CJSONMaker</code> configurations were compiled once inside <code>CRoxieServerXmlParseActivityFactory</code> (or <code>CRoxieXmlReadActivityFactory</code>) similar to the NLP algorithm, the system could omit recompiling string filters every invocation/row.</p>`,17)]))}const u=i(n,[["render",r]]);export{g as __pageData,u as default};
